(()=>{const terms={"assiette": "Montant ou base sur lequel un impôt ou une cotisation est calculé.", "C3S": "Contribution sociale de solidarité des sociétés : prélèvement sur le chiffre d’affaires des entreprises entrant dans son champ.", "CVAE": "Cotisation sur la valeur ajoutée des entreprises : impôt de production dont le calendrier de suppression est fixé par la loi.", "cotisations": "Prélèvements destinés au financement de la protection sociale ; certains ouvrent des droits contributifs.", "CSG-CRDS": "Contributions participant au financement de la protection sociale et au remboursement de la dette sociale.", "prélèvement à la source": "Mode de collecte de l’impôt sur le revenu, retenu notamment sur le salaire avant son versement.", "péréquation": "Mécanisme de redistribution de ressources entre territoires pour réduire leurs écarts de moyens.", "amortissement": "Répartition comptable du coût d’un investissement sur sa durée d’utilisation ; son traitement fiscal dépend des règles applicables.", "droits de mutation": "Impôts perçus lors du transfert de propriété d’un bien, notamment immobilier.", "servitudes": "Contraintes juridiques qui limitent l’usage d’un terrain ou d’un bâtiment.", "permis tacite": "Autorisation pouvant résulter du silence de l’administration à l’issue du délai, dans les cas prévus par la loi.", "loi SRU": "Loi Solidarité et renouvellement urbains, qui prévoit notamment des obligations de logements sociaux pour certaines communes.", "DPE": "Diagnostic de performance énergétique : évaluation de la consommation énergétique et des émissions d’un logement.", "décote": "Réduction du prix par rapport à une valeur de référence.", "barème": "Grille de calcul précisant les taux, seuils ou montants applicables.", "dégressivité": "Diminution progressive d’un avantage à mesure que sa base ou le revenu augmente."};const root=document.querySelector('#texte');if(!root)return;const tip=document.createElement('div');tip.className='definition-popover';tip.id='definition-popover';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.append(tip);let active;function hide(){tip.hidden=true;if(active){active.setAttribute('aria-expanded','false');active.removeAttribute('aria-describedby')}active=null}function show(b){if(active===b&&!tip.hidden){hide();return}hide();active=b;tip.textContent=terms[b.dataset.term];tip.hidden=false;b.setAttribute('aria-expanded','true');b.setAttribute('aria-describedby',tip.id);const r=b.getBoundingClientRect();tip.style.left=Math.max(12,Math.min(r.left,innerWidth-tip.offsetWidth-12))+'px';tip.style.top=Math.max(12,Math.min(r.bottom+9,innerHeight-tip.offsetHeight-12))+'px'}const re=new RegExp(Object.keys(terms).sort((a,b)=>b.length-a.length).map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'gi');root.querySelectorAll('p').forEach(p=>{const w=document.createTreeWalker(p,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('a,button')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});const ns=[];while(w.nextNode())ns.push(w.currentNode);ns.forEach(n=>{const text=n.textContent;const f=document.createDocumentFragment();let last=0;re.lastIndex=0;let m;while((m=re.exec(text))){f.append(text.slice(last,m.index));const key=Object.keys(terms).find(k=>k.toLowerCase()===m[0].toLowerCase());const b=document.createElement('button');b.className='defined-term';b.type='button';b.textContent=m[0];b.dataset.term=key;b.setAttribute('aria-expanded','false');b.setAttribute('aria-label','Définition : '+m[0]);b.addEventListener('click',()=>show(b));f.append(b);last=re.lastIndex}if(last){f.append(text.slice(last));n.replaceWith(f)}})});document.addEventListener('click',e=>{if(!e.target.closest('.defined-term,.definition-popover'))hide()});document.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});addEventListener('scroll',hide,{passive:true});const bar=document.createElement('div');bar.className='reader-progress';document.body.append(bar);function progress(){const rect=root.getBoundingClientRect();const distance=root.offsetHeight-innerHeight;bar.style.width=(Math.max(0,Math.min(1,-rect.top/Math.max(1,distance)))*100)+'%'}addEventListener('scroll',progress,{passive:true});addEventListener('resize',progress);progress();const controls=document.createElement('div');controls.className='reader-controls';controls.innerHTML='<span>Confort de lecture</span><button type="button" aria-label="Réduire le texte">A−</button><button type="button" aria-label="Agrandir le texte">A+</button>';root.prepend(controls);let size=18;controls.querySelectorAll('button').forEach((b,i)=>b.addEventListener('click',()=>{size=Math.max(16,Math.min(24,size+(i?1:-1)));root.style.setProperty('--reader-size',size+'px')}));root.querySelectorAll('[id^="article-"]').forEach(a=>{const h=a.querySelector('h2,h3');if(!h)return;const link=document.createElement('a');link.className='article-permalink';link.href='#'+a.id;link.textContent='#';link.setAttribute('aria-label','Lien direct vers '+h.textContent);h.append(' ',link)})})();